"""Paid event stages, cached square art and real attendance samples through ground depth."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib,os
source=(ROOT/'assets/game.js').read_text();out=ROOT/os.environ.get('GATHERING_ART_OUT','docs/previews/gathering-art');out.mkdir(parents=True,exist_ok=True)
probe=r'''window.__gatherArt={schedule:()=>{const b=readBuild(G.publicPlaces.places.find(p=>p.kind==='square').building);return authorizeCivicGathering(reviewCivicGathering({venue:b.id,start:G.day+1}));},test:(zoom,night,reduced)=>{gameOptions.reducedMotion=reduced;gameOptions.quality='high';applyPresentationOptions();fit();const event=civicCalendarView().events[0],b=readBuild(event.venue),p=iso(b.x,b.y);__townTest.capture({x:p[0],y:p[1],zoom,night});const item=buildingItemsById.get(b.id),before=JSON.stringify(G),first=cv.toDataURL(),actors=gatheringArtResidents(item,gatheringArtIndex.get(b.id));dirty=true;draw();const stable=first===cv.toDataURL();viewRasterKey='';nightEmissionKey='';atlas.clear();atlasBytes=0;staticDirty=true;dirty=true;draw();return{status:event.status,attendance:fromEnd(event.daily)?.attendance||0,actors:actors.length,groundActors:actors.every(a=>a.kind==='vehicle'&&a.v.style==='pedestrian'),stable,coldStable:first===cv.toDataURL(),unchanged:before===JSON.stringify(G),cacheBytes:gatheringArtBytes,cacheSize:gatheringArtSprites.size};},motion:()=>{const cue=civicGatheringCues()[0],item=buildingItemsById.get(cue.venue),before=JSON.stringify(G),old=acc;acc=.1;const a=gatheringArtResidents(item,cue),first=spriteFor(item);acc=.8;const b=gatheringArtResidents(item,cue),sameSprite=first===spriteFor(item);acc=old;return{moves:JSON.stringify(a)!==JSON.stringify(b),sameSprite,zero:gatheringArtResidents(item,{...cue,attendance:0}).length,unchanged:before===JSON.stringify(G)};}};'''
with sync_playwright() as w:
 browser=w.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=browser.new_page(viewport={'width':844,'height':520});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#townSeed').fill('42');p.locator('#newTown').click();p.locator('#pause').click();p.evaluate('__townTest.step(2)');p.keyboard.press('Escape');p.locator('[data-panel=overview]').click();p.locator('[data-civic-projects]').click();p.locator('[data-public-place=square]').click();p.locator('#publicPlaceName').fill('Willow Commons');p.locator('[data-event-choice="0"]').click();p.keyboard.press('Escape');assert p.evaluate('__gatherArt.schedule().ok');scheduled=p.evaluate('__gatherArt.test(2,false,false)');assert scheduled['actors']==0 and scheduled['unchanged'] and scheduled['stable'] and scheduled['coldStable'];p.locator('#view').screenshot(path=str(out/'preparation.png'));p.evaluate('__townTest.step(1)');active=p.evaluate('__townTest.save()');checks=[]
 for width,height,dpr in [(640,360,1),(844,390,2),(1280,720,3)]:
  q=browser.new_page(viewport={'width':width,'height':height},device_scale_factor=dpr);q.on('pageerror',lambda e:errors.append(str(e)));q.set_content(html);q.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));q.locator('#newTown').click();q.locator('#pause').click();q.keyboard.press('Escape');assert q.evaluate('s=>__townTest.load(s)',active)
  for zoom,night,reduced in [(1.6,False,False),(1.6,True,False),(.2,False,False),(1.1,False,True)]:
   r=q.evaluate('([z,n,m])=>__gatherArt.test(z,n,m)',[zoom,night,reduced]);assert r['stable'] and r['coldStable'] and r['unchanged'] and r['groundActors'] and r['actors']<=min(r['attendance'],8) and r['cacheBytes']<=4*1024*1024 and r['cacheSize']<=32,r
   if zoom==.2 or reduced:assert r['actors']==0,r
   r['renderBenchMs']=q.evaluate('__townTest.renderBench(30)');checks.append({'viewport':[width,height,dpr],'zoom':zoom,'night':night,'reduced':reduced,**r})
   if width==844 and zoom==1.6:q.locator('#view').screenshot(path=str(out/('active-night.png' if night else 'active-day.png')))
  q.close()
 p.evaluate('__gatherArt.test(1.6,false,false)');motion=p.evaluate('__gatherArt.motion()');assert motion['moves'] and motion['sameSprite'] and motion['zero']==0 and motion['unchanged'],motion;p.evaluate('__townTest.step(3)');finished=p.evaluate('__gatherArt.test(2,false,false)');assert finished['status']=='complete' and finished['actors']==0 and finished['stable'] and finished['coldStable'] and finished['unchanged'];p.locator('#view').screenshot(path=str(out/'finished.png'));bench=p.evaluate('__townTest.renderBench(100)');assert not errors,errors;browser.close()
(out/'checks.json').write_text(json.dumps({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'scheduled':scheduled,'checks':checks,'motion':motion,'finished':finished,'finishedRenderBenchMs':bench,'errors':errors},indent=2)+'\n');print('PASS',len(checks),'DPR/stage/detail cases',motion)
